record.field:
departments = env['hr.department'].search([])
for dept in departments:
    # 1. Cập nhật cho Trưởng phòng chính (manager_id)
    if dept.manager_id and dept.manager_id.department_id != dept:
        log(f"Cập nhật Trưởng phòng {dept.manager_id.name} vào phòng {dept.name}")
        dept.manager_id.write({'department_id': dept.id})

    # 2. Cập nhật cho danh sách Ban quản lý (manager_ids)
    for manager in dept.manager_ids:
        if manager.department_id != dept:
            log(f"Cập nhật Quản lý {manager.name} vào phòng {dept.name}")
            manager.write({'department_id': dept.id})
